import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CiQ1TEvV.js";const _=JSON.parse('{"title":"支持的文件类型","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/supported-files.md","filePath":"zh/reference/supported-files.md","lastUpdated":1785115728000}'),r={name:"zh/reference/supported-files.md"};function a(l,e,n,i,s,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="支持的文件类型" tabindex="-1">支持的文件类型 <a class="header-anchor" href="#支持的文件类型" aria-label="Permalink to &quot;支持的文件类型&quot;">​</a></h1><p>Mneme 可以索引和检索以下文件类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>扩展名</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td></tr><tr><td>Word</td><td><code>.docx</code></td></tr><tr><td>文本和 Markdown</td><td><code>.txt</code>、<code>.md</code>、<code>.markdown</code>、<code>.log</code></td></tr><tr><td>网页和数据</td><td><code>.html</code>、<code>.htm</code>、<code>.json</code>、<code>.csv</code>、<code>.xml</code>、<code>.yaml</code>、<code>.yml</code></td></tr><tr><td>配置文件</td><td><code>.toml</code>、<code>.cfg</code>、<code>.ini</code>、<code>.conf</code></td></tr><tr><td>源代码</td><td><code>.py</code>、<code>.js</code>、<code>.ts</code>、<code>.css</code>、<code>.sql</code>、<code>.sh</code>、<code>.bat</code></td></tr></tbody></table><h2 id="pdf-处理" tabindex="-1">PDF 处理 <a class="header-anchor" href="#pdf-处理" aria-label="Permalink to &quot;PDF 处理&quot;">​</a></h2><p>Mneme 使用 <strong>PyMuPDF</strong>（<code>fitz</code>）作为主要 PDF 解析器，<strong>pdfplumber</strong> 作为回退。这种双策略确保跨不同 PDF 生成方法的稳健文本提取。</p><ul><li>保留词间距以防止拼接问题（如 <code>UniversityofPennsylvania</code>）</li><li>每个 PDF 的前 5 行用作&quot;anchor chunk&quot;以提升检索相关性</li><li>通过 <code>MNEME_MAX_PDF_PAGES</code> 强制执行最大页数</li></ul><h2 id="安全说明" tabindex="-1">安全说明 <a class="header-anchor" href="#安全说明" aria-label="Permalink to &quot;安全说明&quot;">​</a></h2><p>以下文件被<strong>明确拒绝</strong>索引：</p><ul><li><code>.env</code> 文件（防止 API Key 暴露）</li><li>包含 <code>..</code> 的路径（目录遍历保护）</li></ul><h2 id="文档限制" tabindex="-1">文档限制 <a class="header-anchor" href="#文档限制" aria-label="Permalink to &quot;文档限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>默认值</th><th>控制变量</th></tr></thead><tbody><tr><td>最大文件大小</td><td>50 MiB</td><td><code>MNEME_MAX_DOCUMENT_BYTES</code></td></tr><tr><td>最大 PDF 页数</td><td>2000</td><td><code>MNEME_MAX_PDF_PAGES</code></td></tr><tr><td>允许的根目录</td><td>可选</td><td><code>MNEME_DOCUMENT_ROOT</code></td></tr></tbody></table><p>超过这些限制的文件在索引时会被跳过，并显示清晰的日志消息。</p>',12)])])}const f=t(r,[["render",a]]);export{_ as __pageData,f as default};
